# EXPERIMENTAL (round 2b). Hybrid versus the regime model and the events model, in simulations with truth. M3E_det: events from the pipeline's detector; M3E_true: the true events (oracle);
# HYB: events = episodes of the smoothed regime probability (reciprocity-prior HMM, gate 9), then M3E; HMMr: the regime model. Run from the project root:  Rscript experiments/regimes/v2/hybrid_sim.R [N]
args <- commandArgs(TRUE); N <- if (length(args)) as.integer(args[1]) else 40L
source("analysis/00_setup.R"); source("experiments/regimes/v2/lib2.R"); n_cores <- max(1L, min(5L, cfg$cores - 2L)); score <- function(est, var, truth) c(sqrt(mean((est - truth)^2)) / sd(truth), mean(abs(est - truth) <= 1.96 * sqrt(pmax(var, 0))))
one <- function(job) {
  z <- sim_regime(job$scenario, job$seed, osc = list(alpha = 0.2, f_hz = 0.25, lo = 0.3)); s <- z$s; series <- prepare_series(s$rr); dy <- series$dy; tt <- cumsum(dy); tp <- s$x_p + s$z1; base <- fit_ext(series); cp <- cp_search(series, base, min_gain = -Inf); open <- !is.null(cp) && cp$gain >= 9
  rows <- list(); add <- function(m, mode, xp, xpv, xs, xsv, n_ev = NA_integer_) { a <- score(xp, xpv, tp); b <- score(xs, xsv, s$x_s); rows[[length(rows) + 1]] <<- data.table(model = m, mode = mode, rmse_p = a[1], cover_p = a[2], rmse_s = b[1], cover_s = b[2], n_ev = n_ev) }
  both <- function(m, f, n_ev = NA_integer_) for (sm in c(FALSE, TRUE)) { e <- state_estimates(f, sm); add(m, if (sm) "smooth" else "filter", e$xp, e$xpv, e$xs, e$xsv, n_ev) }
  both("M3", base)
  ev_det <- events_from_rr(dy, if (job$scenario == "two") "tilt" else "exercise", cfg$segmentation); both("M3E_det", if (is.null(ev_det)) base else fit_ext(series, list(inputs = list(events = ev_det))), if (is.null(ev_det)) 0L else nrow(ev_det))
  ev_true <- z$ev; ev_true <- data.frame(t0 = ev_true$t0 - z$off, t1 = ev_true$t1 - z$off); ev_true <- ev_true[ev_true$t1 > 20 & ev_true$t0 < max(tt) - 20, ]; ev_true$t0 <- pmax(ev_true$t0, 5); both("M3E_true", fit_ext(series, list(inputs = list(events = ev_true))), nrow(ev_true))
  if (open) { h <- fit_regime(series, 2, cp, base, 7, 0.7, recip = 20); if (isTRUE(h$ok)) { r <- h$run(smooth = TRUE); add("HMMr", "filter", r$X_p, r$X_p_var, r$X_s, r$X_s_var); add("HMMr", "smooth", r$Xs_p, r$Xs_p_var, r$Xs_s, r$Xs_s_var)
      Ws <- regime_smooth(r$W, r$A, h$p$Pi); ev_h <- regime_episodes(Ws, tt); fh <- if (is.null(ev_h)) NULL else tryCatch(fit_ext(series, list(inputs = list(events = ev_h))), error = function(e) NULL)
      if (!is.null(fh) && isTRUE(fh$ok)) both("HYB", fh, nrow(ev_h)) else both("HYB", base, 0L) } }
  else { e <- state_estimates(base, FALSE); add("HMMr", "filter", e$xp, e$xpv, e$xs, e$xsv); add("HYB", "filter", e$xp, e$xpv, e$xs, e$xsv); e <- state_estimates(base, TRUE); add("HMMr", "smooth", e$xp, e$xpv, e$xs, e$xsv); add("HYB", "smooth", e$xp, e$xpv, e$xs, e$xsv) }
  rbindlist(rows)[, `:=`(scenario = job$scenario, sim = job$sim, open = open, n_true = nrow(z$ev))] }
jobs <- unlist(lapply(c("exercise", "regime", "two", "rest"), function(sc) lapply(seq_len(N), function(i) list(scenario = sc, sim = i, seed = id_seed(paste("regimes2", sc, i), cfg$seed)))), recursive = FALSE)
log_msg("Hybrid simulations | %d jobs", length(jobs)); res <- rbindlist(drop_failed(map_recordings(jobs, one, n_cores), "simulation"), fill = TRUE); saveRDS(res, "experiments/regimes/v2/_out/hybrid_sim.rds"); cat("Saved", nrow(res), "rows\n")
m <- res[model == "M3", .(scenario, sim, mode, p0 = rmse_p, s0 = rmse_s)]; x <- merge(res, m, by = c("scenario", "sim", "mode"))
for (md in c("filter", "smooth")) { cat("\n==", md, ": RMSE relative to M3 (%), median ratio, share of simulations worse than M3 (vagal), 95% coverage ==\n"); print(x[mode == md, .(n = .N, vagal = round(100 * (mean(rmse_p) / mean(p0) - 1)), symp = round(100 * (mean(rmse_s) / mean(s0) - 1)), med_v = round(median(rmse_p / p0), 2), med_s = round(median(rmse_s / s0), 2), worse_v = round(100 * mean(rmse_p > p0)), worst_v = round(max(rmse_p / p0), 1), cov_v = round(mean(cover_p), 2), cov_s = round(mean(cover_s), 2), events = round(mean(n_ev, na.rm = TRUE), 1)), by = .(scenario, model)][order(scenario, match(model, c("M3", "M3E_det", "M3E_true", "HMMr", "HYB")))]) }
